/**
 * BLAST 端到端测试：提交 → 轮询（复用应用真实代码路径 src/lib/eval/blast.ts）
 * 用一段中等长度测试序列（人 EGFR 激酶域片段），观察能否正常完成。
 */
import { submitBlastPdb, collectBlastPdb } from '../src/lib/eval/blast'

const seq = ''

console.log('[test] sequence length:', seq.length)
const t0 = Date.now()
try {
  const { rid, rtoe } = await submitBlastPdb(seq, (m) => console.log(`[submit] ${m}`))
  console.log(`[test] submitted RID=${rid} RTOE=${rtoe}s`)
  const hits = await collectBlastPdb(rid, rtoe, (m) => console.log(`[poll ${(Date.now() - t0) / 1000 | 0}s] ${m}`))
  console.log(`[test] DONE in ${((Date.now() - t0) / 1000).toFixed(1)}s, hits=${hits.length}`)
  console.log('[test] top 5:', hits.slice(0, 5).map(h => `${h.pdbId}:${h.identity}%`).join(', '))
} catch (e) {
  console.error(`[test] FAILED after ${((Date.now() - t0) / 1000).toFixed(1)}s:`, e instanceof Error ? e.message : e)
  process.exit(1)
}
